def bisect_left_range(arr, target):
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def mod_inverse_prime(a: int, p: int) -> int:
    if a % p == 0:
        raise ValueError("a is divisible by p; modular inverse does not exist")
    return pow(a, p - 2, p)

